template:
use std::cell::{Ref, RefCell};

struct Data {
    value: String,
}

fn get_val(c: &RefCell<Data>)
    -> Ref<str>
{
    let guard = c.⟦slot1⟧();
    Ref::map(guard, |d| ⟦slot2⟧)
}

fn main() {
    let cell = RefCell::new(Data {
        value: String::from("rust"),
    });
    println!("{}", get_val(&cell));
}

tests:
#[test]
fn retrieves_field_slice() {
    let cell = RefCell::new(Data { value: String::from("hello") });
    assert_eq!(&*get_val(&cell), "hello");
}
